CustomField.formula:
if(
 AddMonths(DateValue(CreatedDate), 3) > TODAY(), "Created "&Text(TODAY() - DateValue(CreatedDate))&" Days Ago",
 if(AddMonths( Details_Last_Verified__c , 3) > TODAY(), "Verified "&Text(TODAY() - Details_Last_Verified__c)&" Days Ago",
 if(AddMonths(  LastActivityDate , 3) > TODAY(), "Activity "&Text(TODAY() - LastActivityDate)&" Days Ago",
"Yes"
)))
